-- Function: public.fn_reassign_event_organizer
-- Backup generated on 2026-11-11 09:05:37

CREATE OR REPLACE FUNCTION public.fn_reassign_event_organizer(p_tenant_id uuid, p_event_id uuid, p_new_user_id uuid, p_reassigned_by uuid, p_branch_id uuid)  RETURNS void  LANGUAGE plpgsql AS $function$ DECLARE     e record;     v_classroom uuid;     v_ok boolean;     v_reason text;     v_old_teacher uuid;     v_new_teacher uuid; BEGIN     SELECT * INTO e FROM events WHERE id = p_event_id AND tenant_id = p_tenant_id FOR UPDATE;     IF NOT FOUND THEN         RAISE EXCEPTION 'Event not found' USING ERRCODE = 'EE404';     END IF;      SELECT ec.classroom_id INTO v_classroom     FROM event_classrooms ec JOIN classrooms c ON c.id = ec.classroom_id     WHERE ec.event_id = p_event_id AND c.branch_id = p_branch_id LIMIT 1;     IF v_classroom IS NULL THEN         RAISE EXCEPTION 'Event does not belong to this branch' USING ERRCODE = 'EE403';     END IF;      -- Serialize per teacher so two admins cannot double-book the same person.     PERFORM pg_advisory_xact_lock(hashtextextended('teacher-slot:' || p_new_user_id::text, 0));      SELECT a.is_available, a.reason INTO v_ok, v_reason     FROM public.fn_get_available_cover_teachers(p_tenant_id, p_branch_id, v_classroom, e.event_date, e.start_time, e.end_time, p_event_id) a     WHERE a.user_id = p_new_user_id;      IF v_ok IS NULL THEN         RAISE EXCEPTION 'Selected teacher is not assigned to this branch' USING ERRCODE = 'EE409';     ELSIF NOT v_ok THEN         RAISE EXCEPTION 'Selected teacher is not available: %', v_reason USING ERRCODE = 'EE409';     END IF;      UPDATE events SET organizer_id = p_new_user_id, updated_at = now() WHERE id = p_event_id;     UPDATE event_tasks SET owner_id = p_new_user_id, updated_at = now()      WHERE event_id = p_event_id AND is_completed = false AND (owner_id = e.organizer_id OR owner_id IS NULL);      SELECT id INTO v_old_teacher FROM teachers WHERE user_id = e.organizer_id AND tenant_id = p_tenant_id LIMIT 1;     SELECT id INTO v_new_teacher FROM teachers WHERE user_id = p_new_user_id AND tenant_id = p_tenant_id LIMIT 1;      IF v_old_teacher IS NOT NULL THEN         UPDATE staff_leaves sl            SET substitute_teacher_id = COALESCE(sl.substitute_teacher_id, v_new_teacher),                reviewed_by_user_id = p_reassigned_by,                coverage_status = CASE WHEN EXISTS (                     SELECT 1 FROM events x JOIN event_classrooms xc ON xc.event_id = x.id                     WHERE x.tenant_id = p_tenant_id AND x.organizer_id = e.organizer_id                       AND x.status NOT IN ('Cancelled','Completed')                       AND x.event_date BETWEEN sl.start_date AND sl.end_date)                   THEN 'Uncovered' ELSE 'Covered' END          WHERE sl.teacher_id = v_old_teacher AND sl.tenant_id = p_tenant_id AND sl.status = 'Approved'            AND e.event_date BETWEEN sl.start_date AND sl.end_date;     END IF;      INSERT INTO audit_log (tenant_id, user_id, action, entity_type, entity_id, details)     VALUES (p_tenant_id, p_reassigned_by, 'EventOrganizerReassigned', 'Event', p_event_id,             jsonb_build_object('from_user_id', e.organizer_id, 'to_user_id', p_new_user_id,                                'event_date', e.event_date, 'classroom_id', v_classroom)); END; $function$ ;
